mapper.select:
select b.*
from BIZ_SCHOOL_RESUME a
    join BIZ_SCHOOL_RESUME_RECORD b on a.ID = b.RESUMES_ID
where b.ACTION_TYPE = #{actionType}
  and b.RESULT = #{result}
  and b.DELETE_FLAG='NOT_DELETE'
  and a.DELETE_FLAG='NOT_DELETE'

    and a.CREATE_TIME >= #{startTime}


    and a.CREATE_TIME <= #{endTime}

select a.* from BIZ_SCHOOL_RESUME_RECORD a join (select RESUMES_ID,ACTION_TYPE,MAX(OPR_TIME) as oprTime from BIZ_SCHOOL_RESUME_RECORD where DELETE_FLAG='NOT_DELETE'
and RESUMES_ID in
#{item}
and ACTION_TYPE in
#{item}
GROUP BY RESUMES_ID,ACTION_TYPE) b on a.RESUMES_ID = b.RESUMES_ID and a.ACTION_TYPE = b.ACTION_TYPE and a.OPR_TIME = b.oprTime
